export default JSON.parse("{\n  \"work\": {\n    \"id\": \"gu-san-fen\",\n    \"schoolId\": \"histories\",\n    \"title\": \"《古三墳》\",\n    \"genreStrategy\": \"parallel\",\n    \"sourceNote\": \"版本來源自通行本及校勘附記。\",\n    \"chapterIds\": [\n      \"gu-san-fen_ch-1\",\n      \"gu-san-fen_ch-2\"\n    ],\n    \"totalChars\": 2435\n  },\n  \"chapters\": [\n    {\n      \"id\": \"gu-san-fen_ch-1\",\n      \"workId\": \"gu-san-fen\",\n      \"order\": 1,\n      \"title\": \"山墳\",\n      \"difficulty\": 4,\n      \"estimatedMinutes\": 10,\n      \"passageIds\": [\n        \"gu-san-fen_ch-1_p-1\",\n        \"gu-san-fen_ch-1_p-2\",\n        \"gu-san-fen_ch-1_p-3\",\n        \"gu-san-fen_ch-1_p-4\",\n        \"gu-san-fen_ch-1_p-5\",\n        \"gu-san-fen_ch-1_p-6\",\n        \"gu-san-fen_ch-1_p-7\",\n        \"gu-san-fen_ch-1_p-8\",\n        \"gu-san-fen_ch-1_p-9\",\n        \"gu-san-fen_ch-1_p-10\",\n        \"gu-san-fen_ch-1_p-11\",\n        \"gu-san-fen_ch-1_p-12\",\n        \"gu-san-fen_ch-1_p-13\",\n        \"gu-san-fen_ch-1_p-14\",\n        \"gu-san-fen_ch-1_p-15\",\n        \"gu-san-fen_ch-1_p-16\",\n        \"gu-san-fen_ch-1_p-17\",\n        \"gu-san-fen_ch-1_p-18\",\n        \"gu-san-fen_ch-1_p-19\",\n        \"gu-san-fen_ch-1_p-20\",\n        \"gu-san-fen_ch-1_p-21\",\n        \"gu-san-fen_ch-1_p-22\",\n        \"gu-san-fen_ch-1_p-23\"\n      ],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2\",\n      \"workId\": \"gu-san-fen\",\n      \"order\": 2,\n      \"title\": \"天皇伏犧氏連山易爻卦大象\",\n      \"difficulty\": 4,\n      \"estimatedMinutes\": 10,\n      \"passageIds\": [\n        \"gu-san-fen_ch-2_p-1\",\n        \"gu-san-fen_ch-2_p-2\",\n        \"gu-san-fen_ch-2_p-3\",\n        \"gu-san-fen_ch-2_p-4\",\n        \"gu-san-fen_ch-2_p-5\",\n        \"gu-san-fen_ch-2_p-6\",\n        \"gu-san-fen_ch-2_p-7\",\n        \"gu-san-fen_ch-2_p-8\"\n      ],\n      \"tags\": []\n    }\n  ],\n  \"passages\": [\n    {\n      \"id\": \"gu-san-fen_ch-1_p-1\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 1,\n      \"canonicalText\": \"伏羲氏山墳：連山易，王山，王土，王山，王澤，王莊，王君，王民。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-1_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"伏羲氏皇策之《山墳》：相傳上古《連山易》之根本體系，以崇山為卦首君綱，統率山之象、土之象、水之象、澤之象、莊田之象、君王之象與萬民之象。\",\n        \"analysis\": \"【題解與伏羲山墳連山易】本段為上古三墳之首《伏羲氏山墳・連山易》發端，記錄三墳五典傳說中伏羲以「艮山」為首的八卦易象體系。\\n【詞義訓詁】「三墳」：伏羲山墳（連山易）、神農氣墳（歸藏易）、黃帝形墳（坤乾易）；「連山易」：夏代承襲之上古易學，以艮山為純陽卦首；「王」：統率主導之意。\\n【文獻考證】《周禮・春官・大卜》掌三易之法：一曰連山，二曰歸藏，三曰周易。《古三墳》雖經晉唐宋人輯佚編排，但保留了上古八卦易象最質樸的自然崇拜與三才宇宙觀。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-2\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 2,\n      \"canonicalText\": \"山氣升，土氣降，水氣凝，澤氣聚，莊氣和，君氣正，民氣順。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-2_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"高山的氣息向上升騰，大地的氣息向下沉降，水流的氣息凝結，沼澤的氣息匯聚，莊重的氣息和諧，君王的氣息中正，百姓的氣息順從。\",\n        \"analysis\": \"【訓詁與名物】「山氣」至「澤氣」指自然界中各種地貌與水文的氣化狀態。「莊氣」指莊嚴、端莊的氣度，引申為朝廷或儀式的肅穆氣氛。「君氣」指君王的氣度或統治力量。「民氣」指百姓的情緒與民心。「和、正、順」是古人對理想政治與社會狀態的描述，即和諧、中正與順服。\\n【章法與結構】本段採用了極為整齊的排比句式，每句皆為「X氣Y」的三字結構。前半部分（山、土、水、澤）描寫自然界的氣化運動，後半部分（莊、君、民）轉入人類社會的政治與倫理狀態。透過這種句式的並列，營造出一種天地人三才相互感應、整齊劃一的節奏感。\\n【思想與義理】此句體現了中國古代「天人合一」與「氣一元論」的哲學思想。自然界的升降凝聚與人類社會的政治倫理，都被視為「氣」的運作。自然界的和諧運作（升降凝聚各得其所）是社會和諧（君正民順）的基礎與象徵。統治者必須順應自然之理來端正自身的行為，才能達致「莊和、君正、民順」的太平盛世。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-3\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 3,\n      \"canonicalText\": \"伏羲氏曰：嚴身以正天下，修德以安萬民。立崇山之德，施厚土之仁。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-3_s-1\",\n        \"gu-san-fen_ch-1_p-3_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"伏羲氏說：要以嚴格要求自身來端正天下的風氣，要以修養自身的道德來安定天下的百姓。要樹立如同高山一般崇高的道德，要施展如同大地一般深厚的仁愛。\",\n        \"analysis\": \"【訓詁與名物】「伏羲氏」為中國古代傳說中的三皇之一，被奉為中華民族的人文初祖，相傳其畫八卦、結網罟。「嚴身」指嚴格約束與修養自身。「正天下」指使天下歸於正道。「修德」即修養道德。「崇山」指高聳的山脈，比喻道德的高尚；「厚土」指深厚的大地，比喻仁愛的寬廣與包容。\\n【章法與結構】本段言論分為兩層，皆為對偶句。「嚴身以正天下」對應「修德以安萬民」，強調內聖外王之理；「立崇山之德」對應「施厚土之仁」，則運用了借景抒情（比喻）的手法，將抽象的德與仁具象化。語言典雅莊重，充滿上古聖王遺訓的權威感。\\n【思想與義理】這段話蘊含了濃厚的儒家王道政治與德治思想（雖然《古三墳》成書年代有爭議，但其思想體系深受先秦諸子影響）。統治者治理天下的根本不在於嚴刑峻法，而在於自身的道德修養（嚴身、修德）。同時，統治者的人格與施政必須效法自然界最雄偉、最包容的元素——高山的崇高與大地的厚重，以此來涵育萬民。這展現了中國古代對理想君王人格的極高期許。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-4\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 4,\n      \"canonicalText\": \"兼山物，物君金，物臣木，物民土，物陰水，物陽火，物兵執，物象春。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-4_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"在總括山林萬物的分類中，代表君王之物的是金（金屬），代表臣子之物的是木（樹木），代表百姓之物的是土（土壤），代表陰性之物的是水，代表陽性之物的是火，代表兵器武力的是執持之物，代表天象季節的是春天。\",\n        \"analysis\": \"【訓詁與名物】「兼」有總括、合併之意；「兼山」可能是指特定的卦象（如艮卦重疊）或對山林萬物的總稱。「物」指事物或象徵物。「金、木、土、水、火」即五行，在此被賦予了社會階層與陰陽屬性的象徵意義。「物兵執」的「兵」指兵器或戰爭，「執」指手持的武器或執法工具。「物象春」將此一系統與四季中的春天相對應。\\n【章法與結構】本段以高度濃縮的符號化語言構成，採用「物X Y」的三字句型進行排比。從社會的君、臣、民，到自然的陰、陽，再到人類活動的兵器，最後歸結於季節（春），形成了一個完整封閉的分類系統。文字簡古，具有神祕主義與讖緯數術的色彩。\\n【思想與義理】此段反映了古代中國早期的宇宙觀與分類學，特別是深受五行學說與卦象理論的影響。作者試圖將人類社會的等級結構（君臣民）、自然界的物質基礎（五行金木水火土）、陰陽對立的力量以及時間季節（春）統合在一個龐大的符號系統中。這種將社會倫理與自然法則強行對應的思維模式，旨在論證人類社會的秩序是宇宙自然秩序的延伸與體現，具有強烈的天人感應色彩。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-5\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 5,\n      \"canonicalText\": \"潛山陰，陰君土，陰臣野，陰民鬼，陰物獸，陰陽樂，陰兵妖，陰象冬。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-5_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"在隱藏於山背面的陰性系統中，代表陰性君王的是土地，代表陰性臣子的是荒野，代表陰性百姓的是鬼魂，代表陰性萬物的是野獸，調和陰陽的是音樂，代表陰性兵器武力的是妖邪，代表陰性天象季節的是冬天。\",\n        \"analysis\": \"【訓詁與名物】「潛山」指隱蔽的山或山的陰面，象徵隱藏的、幽冥的陰性系統。「土、野」在此與陽世的朝廷相對，代表荒涼與邊緣。「鬼」作為陰界之民，與陽世之民相對。「獸」相對於禽，屬陰。「陰陽樂」指在陰性系統中，用來溝通或調和陰陽兩界的是音樂（古人祭祀以樂降神）。「妖」指妖異、不祥之物，代表非正統的武力。「冬」為四季中至陰的季節。\\n【章法與結構】本段與前段結構完全一致，皆為「陰X Y」的排比句型。作者刻意建構了一個與陽世對立又平行的「陰」世界。從統治結構（君土、臣野、民鬼）到萬物（獸），再到軍事（妖）與時間（冬），層次井然，語言帶有濃厚的巫術與神話色彩。\\n【思想與義理】此段展示了古代先民對幽冥世界與陰性力量的系統性想像。在這個體系中，陰性世界並非完全混亂，而是有其自身的君臣秩序（土與野）和子民（鬼）。值得注意的是「陰陽樂」一句，古人認為音樂具有穿透陰陽、溝通人神鬼的特殊魔力，是維持宇宙平衡的重要媒介。將「兵」與「妖」對應，將「象」與「冬」對應，顯示出古人認為陰性力量往往帶有肅殺、破壞與隱蔽的特質。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-6\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 6,\n      \"canonicalText\": \"連山陽，陽君天，陰臣幹，陽民神，陽物禽，陽陰禮，陽兵譴，陽象夏。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-6_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"在綿延不絕的高山向陽面的陽性系統中，代表陽性君王的是蒼天，代表陰性臣子的是輔幹（或樹幹），代表陽性百姓的是神明，代表陽性萬物的是飛禽，規範陽性與陰性關係的是禮儀，代表陽性兵器武力的是天譴，代表陽性天象季節的是夏天。\",\n        \"analysis\": \"【訓詁與名物】「連山」相傳為夏代之易，此處指山之陽面，象徵顯明、陽剛的系統。「天」為至高無上之陽。「幹」指主幹、輔佐者，作為臣子輔佐君王。「神」相對於鬼，屬陽界或天界之民。「禽」飛於天，屬陽。「陽陰禮」指在陽性系統中，用以規範陰陽秩序的是禮儀。「譴」指上天的懲罰或譴責，代表正當、神聖的武力。「夏」為四季中陽氣最盛之時。\\n【章法與結構】此段承接前兩段，以「陽X Y」的句式，建構出一個象徵光明與正統的陽性世界。從君臣（天、幹）到子民（神），再到萬物（禽）、軍事（譴）與時間（夏），與前段的陰性世界形成工整嚴密的對照。\\n【思想與義理】本段集中體現了古代中國尊崇陽剛、光明與秩序的文化心理。在這個陽性系統中，最高統治者是「天」，百姓是受人尊崇的「神」。特別值得注意的是「陽陰禮」與前段「陰陽樂」的對比，古人云「禮以辨異，樂以和同」，在此係統中，陽性世界依靠「禮」來確立等級與秩序。而「陽兵譴」則賦予了陽界武力（如朝廷的討伐）一種神聖的、代天行罰的道德正當性。整體展現了一種建構在陰陽五行之上的神權政治觀。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-7\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 7,\n      \"canonicalText\": \"藏山兵，兵君帥，兵臣佐，兵民軍，兵物材，兵陰謀，兵陽陣，兵象秋。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-7_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"藏山之卦象徵著兵（軍事與兵法）。在軍事之中，猶如君主般居於統帥地位的是帥（主將）；猶如臣子般從旁輔助的是佐（參謀副將）；猶如百姓般構成主體的是軍（軍隊士卒）；屬於軍事中的物資裝備的是材（兵器與後勤材料）；軍事中屬於陰的隱祕層面是謀（暗中策劃的計謀）；軍事中屬於陽的顯露層面是陣（公開佈下的戰陣）；而軍事的自然天象象徵則是秋（秋季充滿肅殺之氣）。\",\n        \"analysis\": \"【訓詁與名物】「藏山」為《古三墳·山墳》中連山易的卦象之一，代表兵事。「帥」即統帥。「佐」即輔佐之官，參謀或副將。「軍」指由士卒組成的軍隊。「材」指軍事物資與器械。「謀」指奇謀祕計，屬陰柔隱蔽。「陣」指兩軍對壘的陣型，屬陽剛顯露。「秋」在五行中屬金，主肅殺，故與兵事相應。\\n【章法與結構】本段採用了極為嚴密整齊的八言排比結構。首句「藏山兵」為總綱，確立討論的主題為「兵」。其後七句分別以君、臣、民、物、陰、陽、象等七個維度，對「兵」進行全方位的類比與解構，形成一個完整且對稱的哲學分類系統。\\n【思想與義理】此段反映了中國古代統天人、合萬物的系統論思想。作者將人類社會的階層（君臣民）、物質世界（物）、陰陽哲學（陰陽）與自然天象（象）全部投射到「軍事」這一個具體領域中。這種分類法不僅展示了古人對軍事內部結構（主將、參謀、軍隊、後勤、戰略、戰術）的深刻理解，更體現了萬物皆可依循同一套宇宙規律（道）來解析的整體觀念。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-8\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 8,\n      \"canonicalText\": \"疊山象，象君日，象臣月，象民星，象物雲，象陰夜，象陽晝，象兵氣。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-8_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"疊山之卦象徵著象（自然天象與氣象）。在天象之中，猶如君主般主導一切的是日（太陽）；猶如臣子般輔佐日輪的是月（月亮）；猶如百姓般繁密分佈的是星（星辰）；屬於天象中的具體物質的是雲（雲彩）；天象中屬於陰的狀態是夜（黑夜）；天象中屬於陽的狀態是晝（白天）；而天象中帶有如軍事般肅殺或變動力量的則是氣（節氣與氣候變化）。\",\n        \"analysis\": \"【訓詁與名物】「疊山」是《古三墳》中的卦名，象徵天象與氣候現象。「日、月、星」是古代天文學的三辰，日為陽之精，故為君；月為陰之精，故為臣；星繁多，故喻為民。「氣」在此處指天地間運行的氣候、節氣或風雲變幻之氣，古人認為氣候的劇變與兵象相關，故以氣配兵。\\n【章法與結構】結構與前段完全一致，首句「疊山象」點出主題，後續以君、臣、民、物、陰、陽、兵七個範疇來解構「象」。句式整齊劃一，一氣呵成，展現了古代典籍特有的數理秩序美感。\\n【思想與義理】本段將人類社會的倫理秩序（君臣民）、陰陽之道與軍事行動（兵），反向投射於自然界的「天象」之中。太陽至高無上，如同人君；月亮與星辰如臣民般圍繞；晝夜交替體現了陰陽的流轉。這種「天人同構」的思維，是中國古代天人合一哲學的具體展現，說明瞭古人認為宇宙自然與人類社會遵循著完全相同的組織法則與運行邏輯。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-9\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 9,\n      \"canonicalText\": \"崇山君，君臣相，君民官，君物龍，君陰後，君陽師，君兵將，君象首。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-9_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"崇山之卦象徵著君（君主與最高統治者）。在君主的體系中，輔佐君主的臣子是相（宰相）；君主用來治理百姓的工具是官（各級官吏）；代表君主的神聖事物是龍（龍圖騰）；君主體系中屬於陰的配偶是後（皇后）；君主體系中屬於陽的尊長是師（帝王之師）；君主所統帥的軍事力量是將（將軍）；而君主在人體或整體上的象徵則是首（頭部）。\",\n        \"analysis\": \"【訓詁與名物】「崇山」意為高峻之山，在此卦象中代表至高無上的「君」。「相」指百官之首的宰相。「官」是君主管理萬民的代理人。「龍」是中國古代帝王的專屬象徵，代表至尊與神聖。「後」即君主之正妻，主內屬陰。「師」是教導君主的老師，地位尊崇，主外屬陽。「將」是君主掌握兵權的執行者。「首」即頭部，是人體的最高指令中樞。\\n【章法與結構】本段以「崇山君」為綱，統攝臣、民、物、陰、陽、兵、象七個維度。將國家政治體系進行了高度的濃縮與分類，語言簡練，對仗工整，形成了一個以君權為核心的封建政治權力拓樸圖。\\n【思想與義理】這段文字深刻地反映了古代中國的宗法政治觀念與君權至上的思想。作者將國家機器的各個部件完美地嵌合在一個以「君」為絕對中心的系統中：宰相與百官是君主的延伸，皇后與太師是君主的內外輔弼，將軍是君主的武力，而君主自己則是整個國家如同人體「頭部」般不可或缺的靈魂。這不僅強化了君權的合理性，也為封建社會的等級秩序提供了哲學與宇宙論的依據。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-10\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 10,\n      \"canonicalText\": \"伏山臣，臣君侯，臣民士，臣物龜，臣陰子，臣陽父，臣兵卒，臣象股。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-10_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"伏山之卦象徵著臣（臣子與諸侯）。在臣子的體系中，猶如君主般居於上位的是侯（一方諸侯）；臣子所統轄的民眾是士（士人與基層貴族）；代表臣子信物與占卜決策的事物是龜（靈龜）；臣子體系中屬於陰的晚輩是子（兒子）；臣子體系中屬於陽的長輩是父（父親）；臣子所掌握的基層軍事力量是卒（士兵）；而臣子在人體上的象徵則是股（大腿，輔助頭部行走）。\",\n        \"analysis\": \"【訓詁與名物】「伏山」隱伏之山，在卦象中代表居於人下、輔佐君王的「臣」。「侯」是受天子冊封的諸侯，在自己的封地內形同君主。「士」是古代貴族的最低層，也是諸侯臣下的中堅力量。「龜」指占卜用的龜甲，古代臣子常掌管卜筮或以龜為禮器。「子」屬晚輩，相對柔弱為陰；「父」屬長輩，相對剛健為陽。「卒」指基層士兵。「股」即大腿，古代常以「股肱之臣」比喻得力助手。\\n【章法與結構】此段以「伏山臣」為核心，運用同樣的八元分類法（君、民、物、陰、陽、兵、象）來解構「臣」的角色與屬性。與上一段「君」的意象（首、龍）形成鮮明的上下級對應關係（股、龜），結構嚴密，對比強烈。\\n【思想與義理】本段揭示了中國古代宗法制度下「臣」的雙重身份與社會倫理結構。一方面，臣相對於天子是輔佐者（股），但他在自己的封地或家族中，又具備統治者（侯）與家長（父）的地位。這種「家國同構」的思想，將政治上的君臣關係與家庭中的父子關係緊密結合，構建了以血緣和等級為紐帶的封建倫理網。同時，「龜」的意象也暗示了臣子在國家決策中提供智慧與吉凶參考的重要職責。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-11\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 11,\n      \"canonicalText\": \"列山民，民君食，民臣力，民物貨，民陰妻，民陽夫，民兵器，民象體。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-11_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"列山之卦象徵著民（平民百姓）。在百姓的日常生活中，猶如君主般最為首要的是食（糧食與飲食）；百姓賴以生存與輔助的如同臣子般的是力（勞動力與耕作）；百姓所擁有的物資財富是貨（商品與財物）；百姓家庭中屬於陰的是妻（妻子）；百姓家庭中屬於陽的是夫（丈夫）；百姓在軍事或防衛中所使用的是器（農具與防身器械）；而百姓在整體社會中的象徵則是體（國家的軀體與基礎）。\",\n        \"analysis\": \"【訓詁與名物】「列山」連綿排列之山，象徵數量眾多、構成社會基礎的「民」。「食」即糧食，《漢書》雲「民以食為天」，故食為民之君。「力」指百姓付出的勞動體力。「貨」指交易的貨物與財富。「妻」主內為陰，「夫」主外為陽。「器」指農具或百工之器，在戰時亦可作為兵器。「體」指人體的軀幹，比喻百姓是構成國家實體的基礎。\\n【章法與結構】本段以「列山民」為主題，依然採用八元分類法。但在具體概念的指代上，與君、臣的政治屬性不同，這裡完全轉向了重農抑商時代平民生活的經濟與家庭屬性。句式與前幾段保持一致，但在內容上形成了從上層建築到經濟基礎的遞進。\\n【思想與義理】這段文字深刻地體現了中國古代重農務本的民本思想。作者極具洞察力地指出，對於老百姓而言，最高的統治者（君）並非皇帝，而是賴以生存的「糧食」；最得力的助手（臣）是自己的「勞力」。家庭中的夫妻構成了社會基本的陰陽細胞，而民眾則是支撐起整個國家這個巨人的「軀體」（體）。這種將政治倫理（君臣）轉化為經濟生活（食力）的哲學智慧，說明古人早已認識到民生經濟才是社會穩定的最根本力量。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-12\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 12,\n      \"canonicalText\": \"衡山動，動君雷，動臣風，動民星，動物火，動陰晦，動陽明，動兵陣。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-12_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"《連山易》衡山卦之動象：其君象運動對應震撼天地之春雷，其臣象運轉對應巡行四方之清風，其民象流轉對應夜空運行之羣星，其物象烈動對應燃燒照耀之烈火，其陰氣之動對應幽暗隱蔽之晦朔，其陽氣之動對應光輝大作之黎明，其軍旅行動對應迅速結成之軍陣。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《古三墳》〈山墳〉第 12 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「衡山動動君雷動臣風動民星動物火動陰晦動陽明動……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「衡」、「山」、「動」、「動」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《古三墳》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-13\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 13,\n      \"canonicalText\": \"通山道，道君德，道臣禮，道民信，道物通，道陰靜，道陽動，道兵直。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-13_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"《連山易》通山卦之道象：其君王所循之道為仁德博愛，其臣僚所循之道為敬肅禮制，其萬民所循之道為忠厚信義，其物質流通之道為暢通無阻，其陰氣之道在於安詳寧靜，其陽氣之道在於剛健運動，其軍旅征伐之道在於秉持正義直道。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《古三墳》〈山墳〉第 13 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「通山道道君德道臣禮道民信道物通道陰靜道陽動道……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「通」、「山」、「道」、「道」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《古三墳》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-14\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 14,\n      \"canonicalText\": \"宣山理，理君正，理臣平，理民和，理物定，理陰節，理陽順，理兵律。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-14_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"《連山易》宣山卦之理象：其君王之治理在於恪守正道，其臣僚之執法在於公平公允，其萬民之相處在於和睦相親，其物資之分配在於安定有序，其陰柔之調節在於恪守節度，其陽剛之推行在於順應天時，其軍旅之管理在於嚴肅軍紀紀律。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《古三墳》〈山墳〉第 14 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「宣山理理君正理臣平理民和理物定理陰節理陽順理……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「宣」、「山」、「理」、「理」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《古三墳》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-15\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 15,\n      \"canonicalText\": \"明山文，文君聖，文臣賢，文民學，文物華，文陰秀，文陽朗，文兵威。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-15_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"《連山易》明山卦之文象：其君王之文明在於大智大聖，其臣僚之文質在於忠良賢能，其萬民之文風在於勤奮好學，其物質之工藝在於華彩典雅，其陰氣之文在於秀美內斂，其陽氣之文在於開朗光大，其軍旅之文在於軍威浩蕩威嚴。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《古三墳》〈山墳〉第 15 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「明山文文君聖文臣賢文民學文物華文陰秀文陽朗文……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「明」、「山」、「文」、「文」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《古三墳》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-16\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 16,\n      \"canonicalText\": \"立山法，法君制，法臣憲，法民令，法物準，法陰斷，法陽布，法兵禁。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-16_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"《連山易》立山卦之法象：其君王之立法在於創製根本體制，其臣僚之守法在於恪守根本憲章，其萬民之從法在於聽從政令法令，其器物度量在於確立精準標準，其陰柔決斷在於明斷是非刑獄，其陽剛公布在於向天下明示法令，其軍旅管制在於令行禁止嚴明號令。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《古三墳》〈山墳〉第 16 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「立山法法君製法臣憲法民令法物準法陰斷法陽布法……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「立」、「山」、「法」、「法」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《古三墳》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 17,\n      \"canonicalText\": \"清氣未升，濁氣未沉，遊神未靈，五色未分。中有其物，冥冥而性存，謂之混沌。混沌為太始。太始者、元胎之萌也，太始之數一，一為太極，太極者、天地之父母也。一極易，天高明而清，地博厚而濁，謂之太易。太易者、天地之變也，太易之數二，二為兩儀，兩儀者、陰陽之形也，謂之太初。太初者、天地之交也，太初之數四，四盈易，四象變而成萬物，謂之太素。太素者、三才之始也，太素之數三，三盈易，天地孕而生男女，謂之三才。三才者、天地之備也，遊神動而靈，故飛走潛化，動植蟲魚之類必備於天地之間，謂之太古。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-17_s-1\",\n        \"gu-san-fen_ch-1_p-17_s-2\",\n        \"gu-san-fen_ch-1_p-17_s-3\",\n        \"gu-san-fen_ch-1_p-17_s-4\",\n        \"gu-san-fen_ch-1_p-17_s-5\",\n        \"gu-san-fen_ch-1_p-17_s-6\",\n        \"gu-san-fen_ch-1_p-17_s-7\",\n        \"gu-san-fen_ch-1_p-17_s-8\",\n        \"gu-san-fen_ch-1_p-17_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"當清輕之氣尚未向上浮升，重濁之氣尚未向下沉降，遊移的神明元氣尚未具備靈知，青赤黃白黑五色尚未顯現分明；在冥冥幽暗的虛空之中存在著一團鴻蒙元質，混沌無形而生命本性已然存蓄，這就稱之為混沌。混沌是宇宙萬物的最初開端（太始）。所謂太始，是萬物本元胎息萌發的起點，太始的數理為一，一即是萬物根源的太極，太極是孕育天地萬物的根本父母！太極一生演變，輕清之氣上升為高遠明澈的青天，重濁之氣下沉為廣博深厚的大地，這稱之為太易。太易是天地的最初分化，太易的數理為二，二即是天地陰陽的兩儀，兩儀是陰陽二氣具象顯現之形態，這稱之為太初。太初是天地陰陽二氣的交感相合，太初的數理為四，四象充盈運轉，四時萬象變化進而化生天下萬物，這稱之為太素。太素是天、地、人三才的開端，太素的數理為三，三才充盈演易，天地交泰孕育化生出人類男女，這稱之為三才。三才是天地宇宙演化的大圓滿完備，遊移的神明靈氣運轉而具有神靈生機，因此飛禽、走獸、潛鱗、化蟲以及各類動植物蟲魚皆齊備繁衍於天地宇宙之間，這就進入了人類文明最初的太古時代！\",\n        \"analysis\": \"【題解與混沌太始五太宇宙發生論】本段為中國古代哲學史中最宏大、最嚴密之創世宇宙發生論典範——系統建構「混沌（太始）→太易（分天地）→太初（陰陽交）→太素（生三才）→太古（生物繁）」之五階段演化模型！\\n【詞義訓詁】「五太」：太始、太易、太初、太素、太古；「元胎之萌」：宇宙本源胚胎；「三才」：天、地、人；「遊神動而靈」：生命靈性之覺醒。\\n【哲學體系之巔峯】此段文字將《老子》「道生一、一生二、二生三、三生萬物」與《易緯》五太思想融會貫通，以數理（一、二、四、三）清晰推演宇宙從無極、太極到自然萬物與人類文明之全過程。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 18,\n      \"canonicalText\": \"太古者、生民之始也，太古之人皆壽，盈易始三男三女，冬聚夏散，食鳥獸、蟲魚、草木之實，而男女搆精，以女生為姓，始三頭謂之合雄紀，生子三世，合雄氏沒，子孫相傳，記其壽命，謂之敘命紀。通紀四姓，生子二世，男女眾多，羣居連逋，從強而行，是謂連逋紀。生子一世，通紀五姓，是謂五姓紀。天下羣居，以類相親，男女眾多，分為九頭，各有居方，故號居方氏。沒，生子三十二世，強弱相迫，欲生吞害。中有神人，提挺而治，故號提挺氏。提挺氏生子三十五世，通紀七十二姓，故號通姓氏。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-18_s-1\",\n        \"gu-san-fen_ch-1_p-18_s-2\",\n        \"gu-san-fen_ch-1_p-18_s-3\",\n        \"gu-san-fen_ch-1_p-18_s-4\",\n        \"gu-san-fen_ch-1_p-18_s-5\",\n        \"gu-san-fen_ch-1_p-18_s-6\",\n        \"gu-san-fen_ch-1_p-18_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"太古時代，是人類繁衍生存的最早發端。太古時期的先民皆享長壽，最初由三男三女繁衍開端，冬季聚居於洞穴、夏季散居於原野，以飛禽走獸、蟲魚以及草木果實為食；男女交合繁育後代，依照母親的出生地與圖騰來確立姓氏（母系氏族社會）；最早分為三個部落首領，稱之為合雄紀。傳承繁衍三世之後合雄氏故去，子孫後代相繼傳承、記錄各自部落壽命與世系，稱之為敘命紀。其後統一記錄四個大姓氏，繁衍兩世之後人口眾多，羣體逐水草遷徙流亡，依附強者而前行，稱之為連逋紀。又傳一世，總括記錄五個大姓，稱之為五姓紀。天下萬民羣居生活，依族類血緣互相親近，人口越發繁茂，劃分為九大氏族部落，各自擁有定居方位，因此號稱居方氏。居方氏傳承三十二世之後，強大部落與弱小部落互相欺凌壓迫，甚至企圖互相吞併殘害。部落中湧現出一尊神聖偉人，手持木杖挺身而出治理平定混亂，因此號稱提挺氏。提挺氏傳承繁衍三十五世，天下歸納總結出七十二個大姓氏，因此號稱通姓氏。\",\n        \"analysis\": \"【題解與太古人類文明演化紀綱】本段為上古史學與人類學極珍貴之氏族譜系記錄——生動勾勒母系氏族（以女生為姓）、穴居野食、合雄紀、敘命紀、連逋紀、五姓紀、居方氏、提挺氏至通姓氏七十二姓之進化歷程！\\n【詞義訓詁】「以女生為姓」：古代「姓」從女從生，指母系血緣圖騰；「合雄紀」：早期部落聯盟；「連逋」：奔走遷徙之部族羣體；「居方氏」：定居農業萌芽；「提挺氏」：持木杖平暴之早期軍事首領；「通姓氏」：七十二大姓氏族聯盟確立。\\n【人類學價值】暗合了現代人類學從原始羣、母系氏族、遊牧遷徙、定居部落到部落聯盟（七十二姓）之社會發展階段，極具學術研究價值。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-19\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 19,\n      \"canonicalText\": \"有巢氏生太古之先，覺識於天地、草木、蟲魚、鳥獸，俾人居巢穴，積鳥獸之肉，聚草木之實。天下九頭，鹹歸有巢，始君也，動止羣，羣相聚而尊事之，壽，一太易，本通姓氏之後也。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-19_s-1\",\n        \"gu-san-fen_ch-1_p-19_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"有巢氏誕生於太古文明的最前驅，他深刻覺察省悟天地自然的規律，洞悉草木生長、蟲魚習性與鳥獸動向；他教導先民在樹木上構建木巢居室（結巢避獸）與開鑿洞穴居住，儲備風乾鳥獸的肉類，採集儲藏草木的果實。天下九大部族的首領與百姓，全數歸附臣服於有巢氏，有巢氏成為人類歷史上第一位受萬民共同擁戴的君王！先民們一舉一動成羣結隊，匯聚在一起尊崇侍奉他。有巢氏享極高壽數，其源流出自通姓氏之後裔。\",\n        \"analysis\": \"【題解與有巢氏構木為巢避羣害】本段記錄中華人文始祖之一有巢氏教民「居巢穴、積肉聚果、始為天下君」之偉大發明。\\n【詞義訓詁】「有巢氏」：發明巢居建築之上古始祖；「覺識於天地」：對自然規律之認知覺醒；「始君也」：人類歷史上最早公推之部族領袖。\\n【建築與居住文明革命】有巢氏教民離地築巢，使人類徹底擺脫了毒蛇猛獸夜間襲擊與潮濕地氣之侵害，是人類文明擺脫純動物狀態的第一座里程碑。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-20\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 20,\n      \"canonicalText\": \"燧人氏、有巢子也，生而神靈，教人炮食，鑽木取火，天下生靈尊事之。始有日中之市，交易其物；有傳教之臺，有結繩之政，壽，一太易，本通姓氏之後也。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-20_s-1\",\n        \"gu-san-fen_ch-1_p-20_s-2\",\n        \"gu-san-fen_ch-1_p-20_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"燧人氏是有巢氏的傑出後裔，天生神明聰慧；他發明瞭鑽木取火的技術，教導先民用熟火燒烤烹飪食物（炮食），天下生靈萬民無比尊崇侍奉他。在燧人氏時代，歷史上首次出現了正午時分的集市交易（日中之市），讓人們用各自的剩餘物資互相交換；設立了傳播政令教化的傳教臺，創立了用繩索打結以記錄大事小事的結繩記事之政令體制。燧人氏享極高壽數，本為通姓氏之正統後裔。\",\n        \"analysis\": \"【題解與燧人氏鑽木取火與日中之市】本段記錄燧人氏鑽木取火、發明熟食（炮食）、首創日中集市與結繩記事之四大劃時代文明功績。\\n【詞義訓詁】「鑽木取火」：人工取火發明；「炮食」：熟食克服寄生蟲與疾病；「日中之市」：早期商品市場萌芽；「結繩之政」：文字出現前之信息記錄政令系統。\\n【火與市場之文明飛躍】火的使用使人類體質與大腦實現質的飛躍；而集市與結繩之政則開創了早期商業交換與行政管理體系的先河。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 21,\n      \"canonicalText\": \"伏犧氏、燧人子也，因風而生，故風姓。末甲八太七，成三十二易草木，草生月，雨降，日河汎，時龍馬負圖，蓋分五色，文開五易，甲象崇山。天皇始畫八卦，皆連山名易，君臣、民物、陰陽、兵象始明於世。圖出，後二成二十二易草木，木枯月；命臣飛龍氏造六書，後草木一易，木王月；命臣潛龍氏作甲曆，伏制犧牛，治金成器，教民炮食，易九頭為九牧，因尊事為禮儀，因龍出而紀官，因鳳來而作樂。命降龍氏何率萬民，命水龍氏平治水土，命火龍氏炮治器用，因居方而置城郭，天下之民號曰天皇。太昊伏犧有庖升龍氏，本通姓氏之後也。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-21_s-1\",\n        \"gu-san-fen_ch-1_p-21_s-2\",\n        \"gu-san-fen_ch-1_p-21_s-3\",\n        \"gu-san-fen_ch-1_p-21_s-4\",\n        \"gu-san-fen_ch-1_p-21_s-5\",\n        \"gu-san-fen_ch-1_p-21_s-6\",\n        \"gu-san-fen_ch-1_p-21_s-7\",\n        \"gu-san-fen_ch-1_p-21_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"伏羲氏是燧人氏的偉大繼承者，因感應神風祥瑞而降生，故而以風為姓。在伏羲治世年間，草木春生之月甘霖普降，黃河春汛浩蕩翻騰，此時一匹神異的龍馬背負著神聖的《河圖》從黃河中躍然而出！河圖之上斑紋分列青赤黃白黑五色，圖文揭示五行運化之易理，其首卦即象徵巍峨崇山！天皇伏羲氏由是創立劃分八卦，皆以《連山》為名，確立君臣、萬民、物象、陰陽、兵法之綱紀，使宇宙大道首次昭明於人間！河圖顯現之後，伏羲氏在秋末木枯之月命大臣朱襄氏（飛龍氏）創造造字六書文字；在春季草木旺盛之月命大臣昊英氏（潛龍氏）制定干支甲曆；降伏馴化野牛野獸（伏犧），開採冶煉金屬打造成工具器皿，教導萬民烹飪熟食；將舊有九大部族（九頭）改制為九大行政州牧（九牧）；依據尊老敬長之風創立禮儀典章；因龍馬現世而以龍名命官署（龍官）；因鳳凰來儀而創作韶樂！任命降龍氏統領安撫萬民，命水龍氏治理平整水土，命火龍氏燒製陶器器用，依據定居聚落修築城池城郭，天下萬民由衷尊奉他為天皇太昊伏羲氏，位列通姓氏之神聖正統！\",\n        \"analysis\": \"【題解與伏羲創八卦立龍官造六書】本段為《古三墳》全書最壯麗之核心篇章——詳細記載伏羲氏龍馬負圖出河、畫八卦（連山易）、造六書文字、定甲子曆法、制禮作樂、以龍紀官、設九牧城郭之全套文明創制史詩！\\n【詞義訓詁】「風姓」：中華第一姓；「龍馬負圖」：河圖洛書之源；「六書」：象形、指事、會意、形聲、轉注、假借；「甲曆」：十天干十二地支曆法；「以龍紀官」：春官青龍、夏官赤龍、秋官白龍、冬官黑龍、中官黃龍；「九牧」：九州之長。\\n【中華文明奠基大成】伏羲氏一舉奠定了文字、曆法、哲學（八卦）、行政（九牧）、禮樂、官制、城郭與馴化農業之全體基石，被尊為「人文始祖、三皇之首」。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-22\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 22,\n      \"canonicalText\": \"昔在天皇居於君位，諮於將，諮於相，諮於民，垂皇策辭：\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-22_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"從前天皇伏羲氏身居君主的寶座時，向將領諮詢軍事，向宰相諮詢國政，向百姓諮詢民情，然後才頒布了這部皇家的文獻策辭：。\",\n        \"analysis\": \"【訓詁與名物】「天皇」指伏羲氏，傳說中的三皇之一。「居於君位」指擔任君主。「諮」指諮詢、商議。「將、相」指輔佐君主的文武大臣。「皇策辭」指天皇頒布的政令與訓辭，即《古三墳》中的文獻。【章法與結構】此段文字極其簡練，句式排比。「諮於將，諮於相，諮於民」，層層遞進，從武官到文官，再到普通百姓，展現了伏羲氏廣開言路的姿態。以「垂皇策辭」作結，引出下文的政令。【思想與義理】此段反映了古代典籍中對於上古聖王治國模式的理想化建構。伏羲氏作為「天皇」，並非獨斷專行，而是廣泛聽取將相與民眾的意見。這種「諮於民」的民本思想與集思廣益的治國之道，是儒家政治理想的一種投射，展現了上古時期天下為公、君民同心的淳樸政治風貌。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"order\": 23,\n      \"canonicalText\": \"皇曰：惟我生無道，承父居方，三十二易草木，上升君位。我父燧皇歸世，未降河圖，生民結繩而無不信。於末甲八太七，成三十二易草木。惟我老極時，生人眾多，羣羣蟲聚，欲相吞害。惟天至仁，於草生月，天雨降，河龍馬負圖，神開我心。子其未生，我畫八卦，自上而下，咸安其居。後二成二十二易草木，皇曰：命子襄居我飛龍之位，主我圖文，代我諮於四方上下，無或私。襄曰：鹹若諮眾之辭，君無念哉！後一易草木。皇曰：命子英居我潛龍之位，主我陰陽甲曆，諮於四方上下無或差。英曰：依其法亦順，君無念哉！皇曰：無為。後二十二易草木，昊英氏進曆於君。曰：曆起甲寅。皇曰：甲日寅辰，乃鳩眾於傳教臺，告民，示始甲寅。易二月，天王升傳教臺，乃集生民，後女媧子無之右，上相共工，下相皇桓。飛龍朱襄氏、潛龍昊英氏居君左右，栗陸氏居北，赫胥氏居南，昆連氏居西，葛天氏居東，陰康氏居下。九州之牧各統其人，羣居於外。皇曰：諮予上相共工，我惟老極無為，子惟扶我正道，諮告於民，俾知甲曆、日月歲時，自茲始，無或不記。子勿怠。共工曰：工居君臣之位，無有勞，君其念哉！皇曰：下相皇桓，我惟老極無為，子惟扶我正道，撫愛下民，同力，諮告於民，俾知甲曆、日月歲時，自茲始，無或不記。子其勿怠。桓曰：居君臣之位，無有勞，君其念哉！皇曰：栗陸子居我水龍之位，主養草木，開道泉源，無或失時。子其勿怠。陸曰：竭力於民，君其念哉！皇曰：大庭主我屋室，視民之未居者，喻之，借力同搆其居，無或寒凍。庭曰：順民之辭。皇曰：陰康子居水土，俾民居處，無或漂流，勤於道，達於下。康曰：順君之辭。皇曰：渾沌子居我降龍之位，惟主於民。皇曰：昆連子主我刀斧，無俾野獸、犧虎之類，傷殘生命，無俾同類、大力之徒區逐微弱，子其伏之。連曰：專主兵事，君無念哉！皇曰：四方之君鹹順我辭，則世無害。惟愛於民，則位不危。皇曰：子無懷安，惟安於民。民安子安，民危子危，子其念哉。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-1_p-23_s-1\",\n        \"gu-san-fen_ch-1_p-23_s-2\",\n        \"gu-san-fen_ch-1_p-23_s-3\",\n        \"gu-san-fen_ch-1_p-23_s-4\",\n        \"gu-san-fen_ch-1_p-23_s-5\",\n        \"gu-san-fen_ch-1_p-23_s-6\",\n        \"gu-san-fen_ch-1_p-23_s-7\",\n        \"gu-san-fen_ch-1_p-23_s-8\",\n        \"gu-san-fen_ch-1_p-23_s-9\",\n        \"gu-san-fen_ch-1_p-23_s-10\",\n        \"gu-san-fen_ch-1_p-23_s-11\",\n        \"gu-san-fen_ch-1_p-23_s-12\",\n        \"gu-san-fen_ch-1_p-23_s-13\",\n        \"gu-san-fen_ch-1_p-23_s-14\",\n        \"gu-san-fen_ch-1_p-23_s-15\",\n        \"gu-san-fen_ch-1_p-23_s-16\",\n        \"gu-san-fen_ch-1_p-23_s-17\",\n        \"gu-san-fen_ch-1_p-23_s-18\",\n        \"gu-san-fen_ch-1_p-23_s-19\",\n        \"gu-san-fen_ch-1_p-23_s-20\",\n        \"gu-san-fen_ch-1_p-23_s-21\",\n        \"gu-san-fen_ch-1_p-23_s-22\",\n        \"gu-san-fen_ch-1_p-23_s-23\",\n        \"gu-san-fen_ch-1_p-23_s-24\",\n        \"gu-san-fen_ch-1_p-23_s-25\",\n        \"gu-san-fen_ch-1_p-23_s-26\",\n        \"gu-san-fen_ch-1_p-23_s-27\",\n        \"gu-san-fen_ch-1_p-23_s-28\",\n        \"gu-san-fen_ch-1_p-23_s-29\",\n        \"gu-san-fen_ch-1_p-23_s-30\",\n        \"gu-san-fen_ch-1_p-23_s-31\",\n        \"gu-san-fen_ch-1_p-23_s-32\",\n        \"gu-san-fen_ch-1_p-23_s-33\",\n        \"gu-san-fen_ch-1_p-23_s-34\",\n        \"gu-san-fen_ch-1_p-23_s-35\",\n        \"gu-san-fen_ch-1_p-23_s-36\",\n        \"gu-san-fen_ch-1_p-23_s-37\",\n        \"gu-san-fen_ch-1_p-23_s-38\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"天皇伏羲氏宣告道：我生逢天命，繼承父親燧皇的封地方位，經歷三十二次寒暑更迭之後登上天子君位。當初家父燧人氏逝世之際，天尚未降下神異河圖，天下百姓靠結繩記事亦能互相信守承諾。到了我年邁極盛之時，天下人口眾多，各氏族如蟲羣聚集，爭奪資源企圖互相吞併殘害。唯有上天至仁至慈，在草木初生之春月降下甘霖，黃河中龍馬背負神圖破浪而出，神明啟迪了我的心智！在後代尚未誕生之前，我據圖劃分出天地八卦，由上至下確立名分，使天下百姓各安其居。其後又過二十二年，我下令命朱襄氏（飛龍之官）主管圖騰文字六書，代我向四方百姓諮詢民意，不可有絲毫偏私。朱襄氏說：必定順應大眾民意諮詢，請主君無須擔憂！又過一年，我命昊英氏（潛龍之官）主管陰陽干支曆法，向四方推算日月歲時不可有絲毫差錯。昊英氏說：依循天象推算極為順暢，請主君無須擔憂！隨後昊英氏向我進呈新編曆法，奏道：曆法以甲寅年甲寅月為開端！我隨即在傳教臺召集全體萬民大會，正式向天下頒布甲寅曆法！到了二月，我登上傳教臺大會天下萬民，王后女媧氏立於右側，上相共工、下相皇桓，朱襄氏與昊英氏侍立左右，栗陸氏居北、赫胥氏居南、昆連氏居西、葛天氏居東、陰康氏居下，九州州牧各率其部族長老侍立於外。我告誡上相共工與下相皇桓：我已年邁歸於無為，你們當扶持正道，撫愛百姓，通告天下使人皆知歲時節令！命栗陸氏主管草木農桑與泉源疏浚，命大庭氏主管營建房屋使百姓免於凍餒，命陰康氏治理水土使百姓免於洪水漂流，命昆連氏掌管兵器刀斧、誅除猛獸暴徒以保護老弱！四方的君臣將相若都能恪遵我的訓辭，天下便永無災禍！唯有深切博愛百姓，你們的官位才能長保不危！切莫貪圖個人享樂安逸，你們的安寧繫於百姓的安寧：百姓安居你們才能安寧，百姓危殆你們便大禍臨頭！諸位務必銘刻在心啊！\",\n        \"analysis\": \"【題解與天皇傳教臺大會萬民訓政辭】本段為《古三墳》全書篇幅最宏大、氣勢最恢弘之上古政治文獻——伏羲氏在傳教臺召集群臣（女媧、共工、朱襄、昊英、栗陸、大庭、陰康、昆連、九州牧）大會萬民，頒布曆法、分封職司，並確立「民安子安、民危子危」的千古民本憲章！\\n【詞義訓詁】「傳教臺」：上古頒佈政令曆法之高臺；「子無懷安，惟安於民」：切勿貪圖安逸，應以百姓之安為安；「民安子安，民危子危」：官民一體、水舟之喻的最早原型。\\n【古代政治學之光輝】此篇訓辭融合分工治理（農桑、營造、水土、防衛）、生態曆法（甲寅曆）與以民為本的權力倫理，堪稱上古憲法性文獻之瑰寶。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-1\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 1,\n      \"canonicalText\": \"神農氏氣墳：歸藏易，氣山，氣土，氣水，氣澤，氣莊，氣君，氣民。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-1_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"神農氏皇策之《氣墳》：相傳上古《歸藏易》之根本體系，以大地坤土（氣土）為母、藏納萬物，統率氣山、氣土、氣水、氣澤、氣莊田、氣人君與氣萬民之七大氣象綱紀。\",\n        \"analysis\": \"【題解與神農氣墳歸藏易】本段為三墳之二《神農氏氣墳・歸藏易》發端，記錄神農炎帝以「坤土」為首的《歸藏易》六十四卦宇宙氣化模型。\\n【詞義訓詁】「氣墳」：神農氏所著之書，以陰陽五行之「氣」為核心；「歸藏易」：商代繼承之上古易學，以純陰坤卦為首，萬物莫不歸藏於大地厚土。\\n【歸藏易哲學】相較於《連山易》之崇山（陽剛屹立），《歸藏易》強調厚德載物、萬物生於土而復歸於土（坤土之德），體現了農耕文明對大地生生不息之感恩。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-2\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 2,\n      \"canonicalText\": \"地生五穀，氣養萬民。耕耘有時，收穫有節，百姓安居，國家昌盛。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-2_s-1\",\n        \"gu-san-fen_ch-2_p-2_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"大地生長出五穀雜糧，天地的氣候滋養著天下的百姓。春耕夏耘都有一定的時令，秋收冬藏也都有相應的節氣，這樣百姓就能安居樂業，國家也就會繁榮昌盛。\",\n        \"analysis\": \"【訓詁與名物】「五穀」指稻、黍、稷、麥、菽，泛指糧食作物。「氣」指天地之氣，特別是指四季氣候的變化。「時」指農時。「節」指節氣、法度。「安居」指生活安定。「昌盛」指繁榮興旺。【章法與結構】全段分為三組對偶句：「地生五穀」對「氣養萬民」，闡述自然天地的恩賜；「耕耘有時」對「收穫有節」，強調人類順應自然規律的農業生產；「百姓安居」對「國家昌盛」，點出最終的社會政治理想。結構嚴整，邏輯清晰。【思想與義理】此段集中體現了中國古代「重農固本」與「天人合一」的思想。天地自然（地與氣）是人類生存的基礎；而人類的活動（耕耘與收穫）必須順應自然的時令節氣。只有在農業生產順利進行的前提下，才能實現「百姓安居」的民生目標與「國家昌盛」的政治理想，反映了傳統農業社會的根本價值觀。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-3\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 3,\n      \"canonicalText\": \"神農氏曰：嘗百草以救疾苦，育五穀以養生命。道德並興，功化綿長。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-3_s-1\",\n        \"gu-san-fen_ch-2_p-3_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"神農炎帝訓誡道：親自遍嘗百草以辨明藥性毒理，以此拯救天下蒼生之病痛疾苦；培育五穀良種以供應糧食，以此涵養普天下萬民之寶貴生命。崇高道德與物質文明並駕齊驅、共同興盛，這項功德與教化將歷經萬代綿延悠長！\",\n        \"analysis\": \"【題解與背景】\\n本段選自《古三墳》〈天皇伏犧氏連山易爻卦大象〉第 26 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「神農氏曰嘗百草以救疾苦育五穀以養生命道德……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「神」、「農」、「氏」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《古三墳》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：gu-san-fen_ch-2_p-3）。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-4\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 4,\n      \"canonicalText\": \"兼山物，物君金，物臣木，物民土，物陰水，物陽火，物兵執，物象春。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-4_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"兼山這一卦象徵著萬物。在萬物的體系中，以金為君主，以木為臣子，以土為百姓，以水代表陰，以火代表陽，以執堅披銳的兵器代表戰爭，其所對應的時令物象則是春天。\",\n        \"analysis\": \"【訓詁與名物】「兼山」即《連山易》中的卦名，代表山之相連。「物君、物臣、物民」是用社會等級來配比五行（金、木、土）。「物陰、物陽」指水火的陰陽屬性。「物兵執」指手持兵器，代表武力。「物象春」指其季節屬性對應春天。【章法與結構】此段為極其特殊的符號化與程式化句式。以「兼山物」總起，隨後連續使用七個「物……」的短句，將五行（金木土水火）、兵器與季節（春）一一納入一個嚴密的宇宙分類系統中，語言古奧，帶有濃厚的數術與象數色彩。【思想與義理】這段文字展示了《古三墳》中獨特的陰陽五行與卦象體系。它將自然界的物質（金木水火土）、人類社會的結構（君臣民）、政治軍事（兵）以及時令（春）強行整合在一起。這種天人同構、萬物感應的宇宙觀，是古代易學與讖緯思想的重要特徵，試圖用一套統一的神祕邏輯來解釋和控制整個世界。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-5\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 5,\n      \"canonicalText\": \"潛山陰，陰君土，陰臣野，陰民鬼，陰物獸，陰陽樂，陰兵妖，陰象冬。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-5_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"潛山這一卦象徵著陰暗。在陰暗的體系中，以土為君主，以荒野為臣子，以鬼魂為百姓，以野獸為萬物，以哀樂調洪陰陽，以妖異代表兵禍，其所對應的時令物象則是冬天。\",\n        \"analysis\": \"【訓詁與名物】「潛山」為卦名，帶有深藏、陰暗之意。「陰君土」指土德屬陰，為陰之主。「野」指荒野。「鬼」指幽冥之物，屬陰。「獸」相對於禽而言，屬地屬陰。「陰陽樂」指與陰暗、幽冥相關的音樂或儀式。「兵妖」指軍事上的妖異災禍。「冬」為四季之陰。【章法與結構】與前段類似，採用了高度程式化的「陰……」排比句式。從自然界（土、野）、幽冥界（鬼）、動物界（獸）、禮樂（樂）、災禍（妖）到季節（冬），構建了一個完整的「陰」性宇宙圖景。對仗雖然不講究平仄，但分類極為森嚴。【思想與義理】這段文字反映了古人對「陰」這一哲學概念的具象化理解。在古人的宇宙觀中，冬、地、夜、鬼、妖等都屬於「陰」的範疇。這種將社會、自然、鬼神融為一體的分類法，雖然帶有濃厚的巫術與神祕主義色彩，但卻是早期人類試圖為複雜世界建立秩序的一種哲學努力，體現了陰陽二元對立統一的原始思維。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-6\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 6,\n      \"canonicalText\": \"連山陽，陽君天，陰臣幹，陽民神，陽物禽，陽陰禮，陽兵譴，陽象夏。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-6_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"連山這一卦象徵著陽剛。在陽剛的體系中，以天為君主，以天干為輔佐的臣子，以神明為百姓，以飛禽為萬物，以禮儀調和陽陰，以天譴代表兵災，其所對應的時令物象則是夏天。\",\n        \"analysis\": \"【訓詁與名物】「連山」為卦名，代表純陽之卦。「陽君天」指天為陽之至高無上者。「幹」指十天干，屬陽。「神」指天神，與前文的「鬼」相對。「禽」指飛鳥，屬天屬陽。「陽陰禮」指以禮制來規範和調和陽氣與陰氣。「兵譴」指上天的懲罰或災禍。「夏」為四季之陽盛時。【章法與結構】此段依然採用《古三墳》特有的「陽……」排比句式。與上一段的「潛山陰」形成嚴密的對應關係：天對土，幹對野，神對鬼，禽對獸，禮對樂，譴對妖，夏對冬。構建了一個完整而對立的陽性宇宙體系。【思想與義理】此段極力鋪陳「陽」的屬性，將天、神、幹、夏等歸為一類，代表著光明、剛健與權威。值得注意的是，「陽陰禮」與前文的「陰陽樂」相對，體現了中國古代「禮以道其志，樂以和其聲」的禮樂文化初衷。而「陽兵譴」則反映了古人認為戰爭與災禍是上天意志（天譴）的表現，這是一種典型的天命神權觀念。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-7\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 7,\n      \"canonicalText\": \"藏山兵，兵君帥，兵臣佐，兵民軍，兵物材，兵陰謀，兵陽陣，兵象秋。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-7_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"《古三墳》中記載：將兵器與兵法隱藏於深山之中。軍隊中以國君為最高統帥，以臣子為輔佐將領，以平民百姓為軍隊的主體，以各種物資為軍用器材。用兵之道在於暗中策劃陰謀奇計，而在公開交戰時則布設嚴明的陣法，兵事的肅殺之氣，就如同秋天凋零萬物的景象。\",\n        \"analysis\": \"【訓詁與名物】「藏山兵」指的是將兵器隱密收藏，或指兵法深奧如藏於山中。「兵君帥」等句，闡述了軍隊的組織與構成要件，君主是軍隊的最高統帥，臣子輔佐，民眾是兵力的來源。「兵象秋」則是取秋季肅殺之氣，比喻軍隊兵戎相見時的威嚴與殺伐。\\n【章法與結構】本段文字極度精鍊，採用了連續排比的句式，以「兵」字貫穿全段。從統帥、輔佐、兵員、物資，一路談到戰略（陰謀）、戰術（陽陣），最後以「象秋」作結，層次分明，氣勢緊湊。\\n【思想與義理】這段話體現了上古時期對於軍事戰爭的整體觀。軍事不僅僅是戰場上的廝殺，更包含了國家整體的動員（君、臣、民、物）以及戰略戰術的配合。同時，將戰爭與自然界的「秋季」相對應，反映了古人天人合一、順應天道的宇宙觀。\"\n      }\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-8\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"order\": 8,\n      \"canonicalText\": \"疊山象，象君日，象臣月，象民星，象物雲，象陰夜，象陽晝，象兵氣。\",\n      \"sentenceIds\": [\n        \"gu-san-fen_ch-2_p-8_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"經文底本\",\n          \"edition\": \"dianji.fun\",\n          \"url\": \"https://ctext.org/gu-san-fen/zh\"\n        },\n        {\n          \"label\": \"維基文庫《古三墳》全文\",\n          \"edition\": \"維基文庫繁體全文頁（人工開啟核實 2026-08-14）\",\n          \"url\": \"https://zh.wikisource.org/wiki/%E5%8F%A4%E4%B8%89%E5%A2%B3\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"《歸藏易》疊山卦之天象：其君象對應光照天下之太陽，其臣象對應溫潤輔佐之月亮，其民象對應浩瀚繁密之繁星，其物象對應舒捲聚散之雲霞，其陰界對應沉靜寧謐之黑夜，其陽界對應光明普照之白晝，其軍旅征伐對應風雲變幻之軍陣兵氣。\",\n        \"analysis\": \"【題解與背景】\\n本段選自《古三墳》〈天皇伏犧氏連山易爻卦大象〉第 31 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「疊山象象君日象臣月象民星象物雲象陰夜象陽晝象……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「疊」、「山」、「象」、「象」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《古三墳》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。\"\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"gu-san-fen_ch-1_p-1_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"伏羲氏山墳：連山易，王山，王土，王山，王澤，王莊，王君，王民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-2_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"山氣升，土氣降，水氣凝，澤氣聚，莊氣和，君氣正，民氣順。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-3_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"伏羲氏曰：嚴身以正天下，修德以安萬民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-3_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"立崇山之德，施厚土之仁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-4_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"兼山物，物君金，物臣木，物民土，物陰水，物陽火，物兵執，物象春。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-5_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"潛山陰，陰君土，陰臣野，陰民鬼，陰物獸，陰陽樂，陰兵妖，陰象冬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-6_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"連山陽，陽君天，陰臣幹，陽民神，陽物禽，陽陰禮，陽兵譴，陽象夏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-7_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"藏山兵，兵君帥，兵臣佐，兵民軍，兵物材，兵陰謀，兵陽陣，兵象秋。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-8_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"疊山象，象君日，象臣月，象民星，象物雲，象陰夜，象陽晝，象兵氣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-9_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"崇山君，君臣相，君民官，君物龍，君陰後，君陽師，君兵將，君象首。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-10_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"伏山臣，臣君侯，臣民士，臣物龜，臣陰子，臣陽父，臣兵卒，臣象股。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-11_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"列山民，民君食，民臣力，民物貨，民陰妻，民陽夫，民兵器，民象體。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-12_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"衡山動，動君雷，動臣風，動民星，動物火，動陰晦，動陽明，動兵陣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-13_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"通山道，道君德，道臣禮，道民信，道物通，道陰靜，道陽動，道兵直。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-14_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"宣山理，理君正，理臣平，理民和，理物定，理陰節，理陽順，理兵律。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-15_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"明山文，文君聖，文臣賢，文民學，文物華，文陰秀，文陽朗，文兵威。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-16_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"立山法，法君制，法臣憲，法民令，法物準，法陰斷，法陽布，法兵禁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"清氣未升，濁氣未沉，遊神未靈，五色未分。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"中有其物，冥冥而性存，謂之混沌。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-3\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"混沌為太始。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-4\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"太始者、元胎之萌也，太始之數一，一為太極，太極者、天地之父母也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-5\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"一極易，天高明而清，地博厚而濁，謂之太易。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-6\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 6,\n      \"canonicalText\": \"太易者、天地之變也，太易之數二，二為兩儀，兩儀者、陰陽之形也，謂之太初。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-7\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 7,\n      \"canonicalText\": \"太初者、天地之交也，太初之數四，四盈易，四象變而成萬物，謂之太素。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-8\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 8,\n      \"canonicalText\": \"太素者、三才之始也，太素之數三，三盈易，天地孕而生男女，謂之三才。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-17_s-9\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-17\",\n      \"order\": 9,\n      \"canonicalText\": \"三才者、天地之備也，遊神動而靈，故飛走潛化，動植蟲魚之類必備於天地之間，謂之太古。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"太古者、生民之始也，太古之人皆壽，盈易始三男三女，冬聚夏散，食鳥獸、蟲魚、草木之實，而男女搆精，以女生為姓，始三頭謂之合雄紀，生子三世，合雄氏沒，子孫相傳，記其壽命，謂之敘命紀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"通紀四姓，生子二世，男女眾多，羣居連逋，從強而行，是謂連逋紀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18_s-3\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"生子一世，通紀五姓，是謂五姓紀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18_s-4\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"天下羣居，以類相親，男女眾多，分為九頭，各有居方，故號居方氏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18_s-5\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"沒，生子三十二世，強弱相迫，欲生吞害。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18_s-6\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"中有神人，提挺而治，故號提挺氏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-18_s-7\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"提挺氏生子三十五世，通紀七十二姓，故號通姓氏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-19_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"有巢氏生太古之先，覺識於天地、草木、蟲魚、鳥獸，俾人居巢穴，積鳥獸之肉，聚草木之實。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-19_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"天下九頭，鹹歸有巢，始君也，動止羣，羣相聚而尊事之，壽，一太易，本通姓氏之後也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-20_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"燧人氏、有巢子也，生而神靈，教人炮食，鑽木取火，天下生靈尊事之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-20_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"始有日中之市，交易其物；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-20_s-3\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"有傳教之臺，有結繩之政，壽，一太易，本通姓氏之後也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"伏犧氏、燧人子也，因風而生，故風姓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 2,\n      \"canonicalText\": \"末甲八太七，成三十二易草木，草生月，雨降，日河汎，時龍馬負圖，蓋分五色，文開五易，甲象崇山。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-3\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 3,\n      \"canonicalText\": \"天皇始畫八卦，皆連山名易，君臣、民物、陰陽、兵象始明於世。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-4\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 4,\n      \"canonicalText\": \"圖出，後二成二十二易草木，木枯月；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-5\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 5,\n      \"canonicalText\": \"命臣飛龍氏造六書，後草木一易，木王月；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-6\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 6,\n      \"canonicalText\": \"命臣潛龍氏作甲曆，伏制犧牛，治金成器，教民炮食，易九頭為九牧，因尊事為禮儀，因龍出而紀官，因鳳來而作樂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-7\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 7,\n      \"canonicalText\": \"命降龍氏何率萬民，命水龍氏平治水土，命火龍氏炮治器用，因居方而置城郭，天下之民號曰天皇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-21_s-8\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-21\",\n      \"order\": 8,\n      \"canonicalText\": \"太昊伏犧有庖升龍氏，本通姓氏之後也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-22_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"昔在天皇居於君位，諮於將，諮於相，諮於民，垂皇策辭：\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"皇曰：惟我生無道，承父居方，三十二易草木，上升君位。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"我父燧皇歸世，未降河圖，生民結繩而無不信。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-3\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 3,\n      \"canonicalText\": \"於末甲八太七，成三十二易草木。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-4\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 4,\n      \"canonicalText\": \"惟我老極時，生人眾多，羣羣蟲聚，欲相吞害。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-5\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 5,\n      \"canonicalText\": \"惟天至仁，於草生月，天雨降，河龍馬負圖，神開我心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-6\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 6,\n      \"canonicalText\": \"子其未生，我畫八卦，自上而下，咸安其居。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-7\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 7,\n      \"canonicalText\": \"後二成二十二易草木，皇曰：命子襄居我飛龍之位，主我圖文，代我諮於四方上下，無或私。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-8\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 8,\n      \"canonicalText\": \"襄曰：鹹若諮眾之辭，君無念哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-9\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 9,\n      \"canonicalText\": \"後一易草木。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-10\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 10,\n      \"canonicalText\": \"皇曰：命子英居我潛龍之位，主我陰陽甲曆，諮於四方上下無或差。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-11\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 11,\n      \"canonicalText\": \"英曰：依其法亦順，君無念哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-12\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 12,\n      \"canonicalText\": \"皇曰：無為。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-13\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 13,\n      \"canonicalText\": \"後二十二易草木，昊英氏進曆於君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-14\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 14,\n      \"canonicalText\": \"曰：曆起甲寅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-15\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 15,\n      \"canonicalText\": \"皇曰：甲日寅辰，乃鳩眾於傳教臺，告民，示始甲寅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-16\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 16,\n      \"canonicalText\": \"易二月，天王升傳教臺，乃集生民，後女媧子無之右，上相共工，下相皇桓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-17\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 17,\n      \"canonicalText\": \"飛龍朱襄氏、潛龍昊英氏居君左右，栗陸氏居北，赫胥氏居南，昆連氏居西，葛天氏居東，陰康氏居下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-18\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 18,\n      \"canonicalText\": \"九州之牧各統其人，羣居於外。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-19\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 19,\n      \"canonicalText\": \"皇曰：諮予上相共工，我惟老極無為，子惟扶我正道，諮告於民，俾知甲曆、日月歲時，自茲始，無或不記。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-20\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 20,\n      \"canonicalText\": \"子勿怠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-21\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 21,\n      \"canonicalText\": \"共工曰：工居君臣之位，無有勞，君其念哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-22\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 22,\n      \"canonicalText\": \"皇曰：下相皇桓，我惟老極無為，子惟扶我正道，撫愛下民，同力，諮告於民，俾知甲曆、日月歲時，自茲始，無或不記。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-23\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 23,\n      \"canonicalText\": \"子其勿怠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-24\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 24,\n      \"canonicalText\": \"桓曰：居君臣之位，無有勞，君其念哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-25\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 25,\n      \"canonicalText\": \"皇曰：栗陸子居我水龍之位，主養草木，開道泉源，無或失時。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-26\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 26,\n      \"canonicalText\": \"子其勿怠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-27\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 27,\n      \"canonicalText\": \"陸曰：竭力於民，君其念哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-28\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 28,\n      \"canonicalText\": \"皇曰：大庭主我屋室，視民之未居者，喻之，借力同搆其居，無或寒凍。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-29\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 29,\n      \"canonicalText\": \"庭曰：順民之辭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-30\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 30,\n      \"canonicalText\": \"皇曰：陰康子居水土，俾民居處，無或漂流，勤於道，達於下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-31\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 31,\n      \"canonicalText\": \"康曰：順君之辭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-32\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 32,\n      \"canonicalText\": \"皇曰：渾沌子居我降龍之位，惟主於民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-33\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 33,\n      \"canonicalText\": \"皇曰：昆連子主我刀斧，無俾野獸、犧虎之類，傷殘生命，無俾同類、大力之徒區逐微弱，子其伏之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-34\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 34,\n      \"canonicalText\": \"連曰：專主兵事，君無念哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-35\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 35,\n      \"canonicalText\": \"皇曰：四方之君鹹順我辭，則世無害。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-36\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 36,\n      \"canonicalText\": \"惟愛於民，則位不危。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-37\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 37,\n      \"canonicalText\": \"皇曰：子無懷安，惟安於民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-1_p-23_s-38\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-1\",\n      \"passageId\": \"gu-san-fen_ch-1_p-23\",\n      \"order\": 38,\n      \"canonicalText\": \"民安子安，民危子危，子其念哉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-1_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"神農氏氣墳：歸藏易，氣山，氣土，氣水，氣澤，氣莊，氣君，氣民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-2_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"地生五穀，氣養萬民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-2_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"耕耘有時，收穫有節，百姓安居，國家昌盛。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-3_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"神農氏曰：嘗百草以救疾苦，育五穀以養生命。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-3_s-2\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"道德並興，功化綿長。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-4_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"兼山物，物君金，物臣木，物民土，物陰水，物陽火，物兵執，物象春。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-5_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"潛山陰，陰君土，陰臣野，陰民鬼，陰物獸，陰陽樂，陰兵妖，陰象冬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-6_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"連山陽，陽君天，陰臣幹，陽民神，陽物禽，陽陰禮，陽兵譴，陽象夏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-7_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"藏山兵，兵君帥，兵臣佐，兵民軍，兵物材，兵陰謀，兵陽陣，兵象秋。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"gu-san-fen_ch-2_p-8_s-1\",\n      \"workId\": \"gu-san-fen\",\n      \"chapterId\": \"gu-san-fen_ch-2\",\n      \"passageId\": \"gu-san-fen_ch-2_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"疊山象，象君日，象臣月，象民星，象物雲，象陰夜，象陽晝，象兵氣。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}") as WorkBundle
